#include "Game/game.h"
#include <cmath>
#include <algorithm>
#include "Config/player_config.h"
#include "GUI/gui_renderer.h"
#include "raylib.h"
#include "Config/math_utils.h"
Game::Game():renderer_(std::make_unique<GameRenderer>()),player_(std::make_unique<Player>(Vector3{25,4,25})),world_(40000,BlockType::Air){Generate();pigs_.emplace_back(Vector3{20,2,23});}
int Game::Index(int x,int y,int z)const{return x*800+y*50+z;}
void Game::Generate(){for(int x=0;x<50;++x)for(int z=0;z<50;++z){int h=2+(int)round(sinf(x*.22F)*.7F+cosf(z*.19F)*.7F);for(int y=0;y<=h;++y)world_[(size_t)Index(x,y,z)]=y==h?BlockType::Grass:y>=h-2?BlockType::Dirt:BlockType::Stone;}for(int x=5;x<46;x+=7)for(int z=5;z<46;z+=8){if(GetRandomValue(0,2)==0)continue;int g=2;while(g<10&&world_[(size_t)Index(x,g+1,z)]!=BlockType::Air)++g;for(int y=g+1;y<=g+4;++y)world_[(size_t)Index(x,y,z)]=BlockType::OakLog;for(int dx=-2;dx<=2;++dx)for(int dz=-2;dz<=2;++dz)for(int dy=2;dy<=5;++dy){int a=x+dx,b=g+dy,c=z+dz;if(a>=0&&a<50&&b<16&&abs(dx)+abs(dz)<=3&&world_[(size_t)Index(a,b,c)]==BlockType::Air)world_[(size_t)Index(a,b,c)]=BlockType::Leaves;}}}
bool Game::Craft(BlockType result,std::initializer_list<std::pair<BlockType,int>> recipe){for(auto [type,count]:recipe)if(player_->Count(type)<count)return false;for(auto [type,count]:recipe)player_->Remove(type,count);player_->Add(result);return true;}
void Game::Update(float dt){if(IsKeyPressed(KEY_ESCAPE)&&!inventory_open_&&!crafting_open_){running_=false;return;}if(IsKeyPressed(KEY_E))inventory_open_=!inventory_open_;if(inventory_open_){if(IsKeyPressed(KEY_C)){if(player_->Remove(BlockType::OakLog))player_->Add(BlockType::Planks,4);else Craft(BlockType::Stick,{{BlockType::Planks,2}});}if(IsKeyPressed(KEY_V))Craft(BlockType::CraftingTable,{{BlockType::Planks,4}});if(IsKeyPressed(KEY_ESCAPE))inventory_open_=false;return;}if(crafting_open_){if(IsKeyPressed(KEY_P))Craft(BlockType::Pickaxe,{{BlockType::Planks,3},{BlockType::Stick,2}});if(IsKeyPressed(KEY_A))Craft(BlockType::Axe,{{BlockType::Planks,3},{BlockType::Stick,2}});if(IsKeyPressed(KEY_S))Craft(BlockType::Sword,{{BlockType::Planks,2},{BlockType::Stick,1}});if(IsKeyPressed(KEY_ESCAPE))crafting_open_=false;return;}
auto&c=player_->Camera();UpdateCamera(&c,CAMERA_FIRST_PERSON);for(int n=0;n<10;++n)if(IsKeyPressed(n==9?KEY_ZERO:KEY_ONE+n))player_->Select(n);Vector3 f=Math3D::Normalize(Vector3{c.target.x-c.position.x,0,c.target.z-c.position.z}),r=Math3D::Normalize(Math3D::Cross(f,Vector3{0,1,0})),m{};if(IsKeyDown(KEY_W))m=Math3D::Add(m,f);if(IsKeyDown(KEY_S))m=Math3D::Subtract(m,f);if(IsKeyDown(KEY_D))m=Math3D::Add(m,r);if(IsKeyDown(KEY_A))m=Math3D::Subtract(m,r);if(Math3D::Length(m)>0){m=Math3D::Scale(Math3D::Normalize(m),(IsKeyDown(KEY_LEFT_SHIFT)?6.5F:4)*dt);c.position.x+=m.x;c.position.z+=m.z;c.target.x+=m.x;c.target.z+=m.z;}static float vy=0;if(IsKeyPressed(KEY_SPACE))vy=7;vy-=18*dt;c.position.y=std::max(2.65F,c.position.y+vy*dt);c.target.y+=vy*dt;player_->Update(dt);
Vector3 h{},a{};if(renderer_->Raycast(world_,c,h,a)){if(IsMouseButtonPressed(MOUSE_BUTTON_LEFT)){int i=Index((int)h.x,(int)h.y,(int)h.z);auto b=world_[(size_t)i];world_[(size_t)i]=BlockType::Air;drops_.push_back({b,{h.x,h.y+.35F,h.z},30});}if(IsMouseButtonPressed(MOUSE_BUTTON_RIGHT)){int target=Index((int)h.x,(int)h.y,(int)h.z);if(world_[(size_t)target]==BlockType::CraftingTable)crafting_open_=true;else if(a.x>=0&&a.x<50&&a.y>=0&&a.y<16&&a.z>=0&&a.z<50){int i=Index((int)a.x,(int)a.y,(int)a.z);auto s=player_->Inventory()[(size_t)player_->Selected()];if(s.type!=BlockType::Air&&s.type!=BlockType::Stick&&s.type!=BlockType::Pickaxe&&s.type!=BlockType::Axe&&s.type!=BlockType::Sword&&world_[(size_t)i]==BlockType::Air){world_[(size_t)i]=s.type;player_->Remove(s.type);}}}}
auto pos=player_->GetPosition();for(auto it=drops_.begin();it!=drops_.end();){it->lifetime-=dt;if(Math3D::Distance(pos,it->position)<1.5F){player_->Add(it->type);it=drops_.erase(it);}else if(it->lifetime<=0)it=drops_.erase(it);else ++it;}}
void Game::Draw()const{ClearBackground(SKYBLUE);renderer_->DrawWorld(world_,*player_,drops_,pigs_);GuiRenderer().Draw(*player_,inventory_open_);if(crafting_open_){DrawRectangle(350,210,580,300,Color{66,53,43,245});DrawRectangleLines(350,210,580,300,RAYWHITE);DrawText("CRAFTING TABLE",505,235,32,WHITE);DrawText("P Pickaxe: 3 Planks + 2 Sticks",420,305,22,RAYWHITE);DrawText("A Axe: 3 Planks + 2 Sticks",420,350,22,RAYWHITE);DrawText("S Sword: 2 Planks + 1 Stick",420,395,22,RAYWHITE);DrawText("Escape to close",530,460,18,LIGHTGRAY);}}
